"""Regenerate every SVG under assets/art and the manifest. Art is code: edit the
generator, never the SVG. Usage: python tools/gen_all.py"""
import os, shutil, sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import svg_lib as L
import gen_icons, gen_science, gen_math, gen_bahasa, gen_subjects, gen_characters, gen_backgrounds, gen_ui_fx_tiles

for d in os.listdir(L.ART) if os.path.isdir(L.ART) else ():
    p = os.path.join(L.ART, d)
    if os.path.isdir(p):
        # .import sidecars are regenerated by Godot; keep nothing stale
        shutil.rmtree(p)

for mod in (gen_icons, gen_science, gen_math, gen_bahasa, gen_subjects, gen_characters, gen_backgrounds, gen_ui_fx_tiles):
    mod.main()

n = L.write_manifest()
ids = [m["category"] + "/" + m["id"] for m in L._manifest]
assert len(ids) == len(set(ids)), "duplicate asset ids"
missing = [m for m in L._manifest if not m.get("bm") and m["category"] != "fx"]
assert not missing, f"assets without a BM name: {[m['id'] for m in missing]}"
print(f"{n} SVG assets written + manifest.json")
